127	func (b *APIBranches) UnmarshalJSON(data []byte) error {
128		if bytes.Equal(data, []byte("null")) {
129			*b = APIBranches{}
130			return nil
131		}
132	
133		var values []string
134		if err := json.Unmarshal(data, &values); err == nil {
135			*b = APIBranches{Values: values}
136			return nil
137		}
138	
139		var sentinel string
140		if err := json.Unmarshal(data, &sentinel); err != nil {
141			return fmt.Errorf("decode branches: %w", err)
142		}
143		if sentinel != "all" {
144			return fmt.Errorf("decode branches: unexpected sentinel %q", sentinel)
145		}
146		*b = APIBranches{All: true}
147		return nil
148	}
