15	func runServer(ctx context.Context, opts Options) (*Dispatch, error) {
16		token, err := lookupCurrentToken()
17		if err != nil {
18			return nil, fmt.Errorf("reading credentials: %w", err)
19		}
20		if token == "" {
21			return nil, errors.New("dispatch requires login — run `entire login`")
22		}
23	
24		now := nowUTC()
25		sinceInput := strings.TrimSpace(opts.Since)
26		if sinceInput == "" {
27			sinceInput = "7d"
28		}
29		since, err := ParseSinceAtNow(sinceInput, now)
30		if err != nil {
31			return nil, err
32		}
33		until, err := ParseUntilAtNow(opts.Until, now)
34		if err != nil {
35			return nil, err
36		}
37		normalizedSince, normalizedUntil := NormalizeWindow(since, until)
38		if !normalizedSince.Before(normalizedUntil) {
39			return nil, errors.New("--since must be before --until")
40		}
41	
42		repos := append([]string(nil), opts.RepoPaths...)
43		orgs := append([]string(nil), opts.Orgs...)
44		if len(orgs) == 0 && len(repos) == 0 {
45			repoRoot, err := paths.WorktreeRoot(ctx)
46			if err != nil {
47				return nil, fmt.Errorf("not in a git repository: %w", err)
48			}
49			repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
50			if err != nil {
51				return nil, fmt.Errorf("open repository: %w", err)
52			}
53			repoFullName, err := resolveRepoFullName(repo)
54			if err != nil {
55				return nil, err
56			}
57			repos = []string{repoFullName}
58		}
59	
60		cloud := NewCloudClient(CloudConfig{BaseURL: api.BaseURL(), Token: token})
61		reqBody := CreateDispatchRequest{
62			Repos:       repos,
63			Orgs:        orgs,
64			Since:       normalizedSince.Format(time.RFC3339),
65			Until:       normalizedUntil.Format(time.RFC3339),
66			Branches:    append([]string(nil), opts.Branches...),
67			AllBranches: opts.AllBranches,
68			Generate:    true,
69			Voice:       resolvedDispatchVoicePreference(opts.Voice),
70		}
71		response, err := cloud.CreateDispatch(ctx, reqBody)
72		if err != nil {
73			return nil, err
74		}
75	
76		dispatch := apiToDispatch(response)
77		if strings.TrimSpace(dispatch.GeneratedText) == "" {
78			return nil, errDispatchMissingMarkdown
79		}
80		return dispatch, nil
81	}
82	
83	func apiToDispatch(response *CreateDispatchResponse) *Dispatch {
84		if response == nil {
85			return &Dispatch{}
86		}
87	
88		repos := make([]RepoGroup, 0, len(response.Repos))
89		for _, repo := range response.Repos {
90			sections := make([]Section, 0, len(repo.Sections))
91			for _, section := range repo.Sections {
92				bullets := make([]Bullet, 0, len(section.Bullets))
93				for _, bullet := range section.Bullets {
94					bullets = append(bullets, Bullet{
95						CheckpointID: bullet.CheckpointID,
96						Text:         bullet.Text,
97						Source:       bullet.Source,
98						Branch:       bullet.Branch,
99						CreatedAt:    parseAPITime(bullet.CreatedAt),
100						Labels:       append([]string(nil), bullet.Labels...),
101					})
102				}
103				sections = append(sections, Section{
104					Label:   section.Label,
105					Bullets: bullets,
106				})
107			}
108			repos = append(repos, RepoGroup{
109				FullName: repo.FullName,
110				Sections: sections,
111			})
112		}
113	
114		generatedText := strings.TrimSpace(response.GeneratedMarkdown)
115		if generatedText == "" {
116			generatedText = strings.TrimSpace(response.GeneratedText)
117		}
118	
119		return &Dispatch{
120			Window: Window{
121				NormalizedSince:   parseAPITime(response.Window.NormalizedSince),
122				NormalizedUntil:   parseAPITime(response.Window.NormalizedUntil),
123				FirstCheckpointAt: parseAPITime(response.Window.FirstCheckpointCreatedAt),
124				LastCheckpointAt:  parseAPITime(response.Window.LastCheckpointCreatedAt),
125			},
126			CoveredRepos:  append([]string(nil), response.CoveredRepos...),
127			Repos:         repos,
128			GeneratedText: generatedText,
129		}
130	}
131	
132	func parseAPITime(value string) time.Time {
133		if value == "" {
134			return time.Time{}
135		}
136		parsed, err := time.Parse(time.RFC3339, value)
137		if err != nil {
138			return time.Time{}
139		}
140		return parsed
141	}
