213	func reachableCheckpointIDsOnHEAD(ctx context.Context, repoRoot string, since time.Time) (map[string]struct{}, error) {
214		cmd := exec.CommandContext(
215			ctx,
216			"git",
217			"-C",
218			repoRoot,
219			"log",
220			"HEAD",
221			"--since="+since.UTC().Format(time.RFC3339),
222			"--grep",
223			"Entire-Checkpoint:",
224			"--format=%B%x00",
225		)
226		output, err := cmd.Output()
227		if err != nil {
228			return nil, fmt.Errorf("list HEAD checkpoint trailers: %w", err)
229		}
230	
231		reachable := make(map[string]struct{})
232		for _, message := range strings.Split(string(output), "\x00") {
233			for _, checkpointID := range trailers.ParseAllCheckpoints(message) {
234				reachable[checkpointID.String()] = struct{}{}
235			}
236		}
237		return reachable, nil
238	}
