28	func runLocal(ctx context.Context, opts Options) (*Dispatch, error) {
29		if len(opts.Orgs) > 0 {
30			return nil, errors.New("--org cannot be used with --local")
31		}
32	
33		now := nowUTC()
34		sinceInput := strings.TrimSpace(opts.Since)
35		if sinceInput == "" {
36			sinceInput = "7d"
37		}
38		since, err := ParseSinceAtNow(sinceInput, now)
39		if err != nil {
40			return nil, err
41		}
42		until, err := ParseUntilAtNow(opts.Until, now)
43		if err != nil {
44			return nil, err
45		}
46		normalizedSince, normalizedUntil := NormalizeWindow(since, until)
47		if !normalizedSince.Before(normalizedUntil) {
48			return nil, errors.New("--since must be before --until")
49		}
50	
51		repoRoots, err := resolveRepoRoots(ctx, opts.RepoPaths)
52		if err != nil {
53			return nil, err
54		}
55	
56		allCandidates := make([]candidate, 0)
57		var candidatesMu sync.Mutex
58		group, groupCtx := errgroup.WithContext(ctx)
59		for _, repoRoot := range repoRoots {
60			group.Go(func() error {
61				candidates, err := enumerateRepoCandidates(groupCtx, repoRoot, opts, normalizedSince, normalizedUntil)
62				if err != nil {
63					return err
64				}
65				candidatesMu.Lock()
66				allCandidates = append(allCandidates, candidates...)
67				candidatesMu.Unlock()
68				return nil
69			})
70		}
71		if err := group.Wait(); err != nil {
72			return nil, fmt.Errorf("enumerate repo candidates: %w", err)
73		}
74	
75		fallback := applyFallbackChain(allCandidates)
76		dispatch := &Dispatch{
77			CoveredRepos: coveredRepos(allCandidates),
78			Repos:        groupBulletsByRepo(fallback.Used),
79			Window: Window{
80				NormalizedSince:   normalizedSince,
81				NormalizedUntil:   normalizedUntil,
82				FirstCheckpointAt: firstAt(fallback.Used),
83				LastCheckpointAt:  lastAt(fallback.Used),
84			},
85		}
86	
87		text, err := generateLocalDispatch(ctx, dispatch, opts.Voice)
88		if err != nil {
89			return nil, err
90		}
91		if strings.TrimSpace(text) == "" {
92			return nil, errDispatchMissingMarkdown
93		}
94		dispatch.GeneratedText = text
95	
96		return dispatch, nil
97	}
