129	func enumerateRepoCandidates(ctx context.Context, repoRoot string, opts Options, since, until time.Time) ([]candidate, error) {
130		repo, err := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
131		if err != nil {
132			return nil, fmt.Errorf("open repository %s: %w", repoRoot, err)
133		}
134	
135		repoFullName, err := resolveRepoFullName(repo)
136		if err != nil {
137			return nil, fmt.Errorf("resolve repo name for %s: %w", repoRoot, err)
138		}
139	
140		branches := opts.Branches
141		if len(branches) == 0 && !opts.AllBranches {
142			currentBranch, err := currentBranchName(repo)
143			if err != nil {
144				return nil, err
145			}
146			branches = []string{currentBranch}
147		}
148		branchSet := make(map[string]struct{}, len(branches))
149		for _, branch := range branches {
150			branchSet[branch] = struct{}{}
151		}
152		reachableCheckpointIDs := map[string]struct{}{}
153		if opts.ImplicitCurrentBranch && !opts.AllBranches {
154			reachableCheckpointIDs, err = reachableCheckpointIDsOnHEAD(ctx, repoRoot, since)
155			if err != nil {
156				return nil, err
157			}
158		}
159	
160		store := checkpoint.NewGitStore(repo)
161		infos, err := store.ListCommitted(ctx)
162		if err != nil {
163			return nil, fmt.Errorf("list committed checkpoints: %w", err)
164		}
165	
166		candidates := make([]candidate, 0, len(infos))
167		for _, info := range infos {
168			if info.CreatedAt.Before(since) || !info.CreatedAt.Before(until) {
169				continue
170			}
171	
172			summary, err := store.ReadCommitted(ctx, info.CheckpointID)
173			if err != nil || summary == nil {
174				continue
175			}
176			if !opts.AllBranches {
177				_, onSelectedBranch := branchSet[summary.Branch]
178				if !onSelectedBranch {
179					if !opts.ImplicitCurrentBranch {
180						continue
181					}
182					if _, reachable := reachableCheckpointIDs[info.CheckpointID.String()]; !reachable {
183						continue
184					}
185				}
186			}
187	
188			localSummary := ""
189			if len(summary.Sessions) > 0 {
190				latestIndex := len(summary.Sessions) - 1
191				if metadata, err := store.ReadSessionMetadata(ctx, info.CheckpointID, latestIndex); err == nil && metadata != nil && metadata.Summary != nil {
192					localSummary = strings.TrimSpace(metadata.Summary.Outcome)
193					if localSummary == "" {
194						localSummary = strings.TrimSpace(metadata.Summary.Intent)
195					}
196				}
197			}
198	
199			commitSubject, _ := findCommitSubjectByCheckpoint(ctx, repoRoot, info.CheckpointID) //nolint:errcheck // missing subject falls through to other fallbacks
200			candidates = append(candidates, candidate{
201				CheckpointID:      info.CheckpointID.String(),
202				RepoFullName:      repoFullName,
203				Branch:            summary.Branch,
204				CreatedAt:         info.CreatedAt,
205				CommitSubject:     commitSubject,
206				LocalSummaryTitle: localSummary,
207			})
208		}
209	
210		return candidates, nil
211	}
